/* Align status with the visible fitted logo rectangle; preserve existing locale text and status dot. */
(()=>{'use strict';let queued=false,current=null,resize=null;const schedule=()=>{if(!queued){queued=true;requestAnimationFrame(update);}};function update(){queued=false;if(document.body.dataset.series!=='s5')return;const brand=document.querySelector('#cx-widget .cx-widget-brand'),logo=brand?.querySelector('img.cx-logo'),status=brand?.querySelector('.cx-status');if(!brand||!logo||!status||!logo.complete||!logo.naturalWidth)return;if(current!==logo){current=logo;resize?.disconnect();if('ResizeObserver'in window){resize=new ResizeObserver(schedule);resize.observe(logo);resize.observe(brand);}}const b=brand.getBoundingClientRect(),r=logo.getBoundingClientRect(),s=getComputedStyle(logo);const pl=parseFloat(s.paddingLeft)||0,pr=parseFloat(s.paddingRight)||0,pt=parseFloat(s.paddingTop)||0,pb=parseFloat(s.paddingBottom)||0,w=Math.max(0,r.width-pl-pr),h=Math.max(0,r.height-pt-pb);let extra=0;if(s.objectFit==='contain'){const scale=Math.min(w/logo.naturalWidth,h/logo.naturalHeight);extra=Math.max(0,(w-logo.naturalWidth*scale)/2);}const offset=Math.max(0,r.left-b.left+pl+extra),value=(Math.round(offset*100)/100)+'px';if(brand.style.getPropertyValue('--s5-status-inset')!==value)brand.style.setProperty('--s5-status-inset',value);}new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['src','class']});document.addEventListener('load',schedule,true);window.addEventListener('resize',schedule,{passive:true});schedule();})();
